recs.append(R(8872488,"حجازی منتو",
"منتو قیمے اور پیاز سے بھرے ہوئے پکوڑے نما ڈمپلنگ ہیں جو بھاپ میں پکائے جاتے ہیں؛ یہ حجاز، خاص طور پر مکہ اور جدہ میں، بخارا سے آئی ہوئی مشہور ڈش ہے، جو دہی کی چٹنی اور تیز ٹماٹر کی چٹنی کے ساتھ پیش کی جاتی ہے۔ اس ترکیب میں آدھا آٹا سالم گندم کا ہے، کم چکنائی والا گوشت، کم چکنائی والا دہی اور تھوڑا نمک ہے، اور منتو بھاپ میں پکائے جاتے ہیں، تلے نہیں جاتے۔",
"4","6 ڈمپلنگ دونوں چٹنیوں کے ساتھ (تقریباً 350 گرام)",
[("آٹے کے لیے","100 گرام سالم گندم کا آٹا"),("آٹے کے لیے","100 گرام سفید آٹا"),("آٹے کے لیے","1 انڈا (50 گرام)"),("آٹے کے لیے","1 چٹکی نمک (1 گرام)"),("آٹے کے لیے","تقریباً 90 ملی لیٹر پانی"),("بھرتے کے لیے","500 گرام کم چکنائی والا گائے کا قیمہ (90% کم چکنائی)"),("بھرتے کے لیے","2 درمیانے پیاز (200 گرام)، کدوکش کیے اور نچوڑے ہوئے"),("بھرتے کے لیے","1 چائے کا چمچ زیرہ، ½ چائے کا چمچ کالی مرچ، ¼ چائے کا چمچ لال مرچ پاؤڈر"),("بھرتے کے لیے","⅓ چائے کا چمچ نمک (2 گرام)"),("بھرتے کے لیے","اسٹیمر کو چکنا کرنے کے لیے 1 چائے کا چمچ زیتون کا تیل (4.5 گرام)"),("دہی کی چٹنی کے لیے","200 گرام کم چکنائی والا دہی"),("دہی کی چٹنی کے لیے","1 لہسن کا جوا (4 گرام)، کچلا ہوا، اور ½ چائے کا چمچ خشک پودینہ"),("تیز چٹنی کے لیے","2 ٹماٹر (200 گرام)"),("تیز چٹنی کے لیے","1 ہری مرچ (10 گرام) اور 1 لہسن کا جوا (4 گرام)"),("تیز چٹنی کے لیے","1 کھانے کا چمچ لیموں کا رس (15 ملی لیٹر) اور 1 مٹھی تازہ دھنیا (10 گرام)")],
["دونوں آٹے کو نمک اور انڈے کے ساتھ ملائیں، پانی تھوڑا تھوڑا ڈالیں اور نرم، ملائم آٹا گوندھیں جو نہ چپکے۔ ڈھانپ کر 30 منٹ رکھ دیں۔","گوشت کو نچوڑے ہوئے پیاز، زیرے، کالی مرچ، مرچ اور نمک کے ساتھ اچھی طرح ملائیں۔","آٹے کو پتلا بیلیں اور 24 چوکور ٹکڑوں (تقریباً 8 سینٹی میٹر) میں کاٹیں۔ ہر ایک کے بیچ میں ایک چمچ بھرتا رکھیں، چاروں کونے اوپر لا کر اچھی طرح دبا کر بند کریں۔","اسٹیمر کی ٹرے پر تیل لگائیں، منتو کو فاصلے سے رکھیں، ابلتے پانی پر رکھیں، ڈھانپیں اور 35–40 منٹ بھاپ دیں یہاں تک کہ بھرتا پک جائے۔","دہی کی چٹنی کے لیے: دہی میں لہسن اور پودینہ ملائیں۔","تیز چٹنی کے لیے: ٹماٹر، مرچ، لہسن، لیموں کا رس اور دھنیا بلینڈر میں موٹا موٹا پیس لیں۔","منتو کو دونوں چٹنیوں کے ساتھ گرم پیش کریں اور اوپر ہلکا سا زیرہ اور کالی مرچ چھڑکیں۔"],
[WC+"منتو تلنے کے بجائے بھاپ میں پکائے گئے ہیں، آدھا آٹا سالم گندم کا ہے، چربی والے گوشت اور گھی کی جگہ 90% کم چکنائی والا گوشت، دہی کم چکنائی والا ہے، اور تیز چٹنی تازہ ٹماٹر کی ہے جس میں نمک نہیں ڈالا گیا۔",
KT+"گوشت، دہی اور ٹماٹر فاسفورس اور پوٹاشیم بڑھاتے ہیں؛ 6 کی جگہ 4 ڈمپلنگ کھائیں، دہی کی چٹنی صرف 2 کھانے کے چمچ لیں، اور تیز چٹنی میں ٹماٹر کی جگہ بھنی ہوئی سرخ مرچ ڈالیں۔",
DT+"ایک حصے (6 ڈمپلنگ) میں تقریباً 48 گرام کاربوہائیڈریٹ ہوتے ہیں؛ اسے بڑے ہرے سلاد کے ساتھ پیش کریں اور اضافی چاول یا روٹی نہ لیں۔",
SF+"ذیابیطس۔",
RF+"Encyclopedia Cooking، Layalina Yummy، Mawdoo3"],[]))
recs.append(R(8874214,"قصیمی فتیت",
"فتیت ایک روایتی نجدی بسکٹ ہے جو القصیم میں مشہور ہے: سالم گندم کے آٹے کی بھربھری گول ٹکیاں جن میں الائچی، ادرک اور زعفران ہوتا ہے، بیک کی جاتی ہیں اور شہد، دار چینی اور کالے لیموں کے شیرے کے ساتھ پیش کی جاتی ہیں۔ اس ترکیب میں معمول کی ایک تہائی سے کم چینی، آدھے سے کم تیل، اور بغیر چکنائی کا پاؤڈر دودھ ہے۔",
"16","1 ٹکیہ (تقریباً 35 گرام) 1 چائے کے چمچ شیرے کے ساتھ",
[("آٹے کے لیے","300 گرام سالم گندم کا آٹا"),("آٹے کے لیے","2 کھانے کے چمچ بغیر چکنائی کا پاؤڈر دودھ (15 گرام)"),("آٹے کے لیے","1 انڈا (50 گرام)"),("آٹے کے لیے","1 چائے کا چمچ بیکنگ پاؤڈر (4 گرام)"),("آٹے کے لیے","60 گرام چینی (5 کھانے کے چمچ)"),("آٹے کے لیے","60 ملی لیٹر ہلکا زیتون کا تیل (55 گرام)"),("آٹے کے لیے","1 چٹکی نمک (1 گرام)"),("آٹے کے لیے","½ چائے کا چمچ پسی الائچی"),("آٹے کے لیے","½ چائے کا چمچ پسی ادرک"),("آٹے کے لیے","1 چٹکی زعفران جو 1 کھانے کے چمچ پانی میں بھگویا ہو (یا ¼ چائے کا چمچ ہلدی)"),("آٹے کے لیے","تقریباً 150 ملی لیٹر پانی"),("شیرے کے لیے","2 کھانے کے چمچ شہد (40 گرام)"),("شیرے کے لیے","60 ملی لیٹر پانی"),("شیرے کے لیے","1 چائے کا چمچ پسی دار چینی"),("شیرے کے لیے","½ چائے کا چمچ پسی الائچی"),("شیرے کے لیے","½ چائے کا چمچ پسا کالا لیموں (لومی)")],
["اوون کو اوپر اور نیچے کی حرارت کے ساتھ 190°C پر گرم کریں اور دو ٹرے پر بیکنگ پیپر بچھائیں۔","انڈے کو چینی، تیل، بھیگے زعفران، الائچی، ادرک اور نمک کے ساتھ پھینٹیں۔","آٹے کو پاؤڈر دودھ اور بیکنگ پاؤڈر کے ساتھ ملائیں، انڈے کے آمیزے میں پانی کے ساتھ تھوڑا تھوڑا ڈالیں اور سخت آٹا گوندھیں جو شکل دینے میں آسان ہو اور نہ چپکے۔","آٹے کو 16 پیڑوں میں تقسیم کریں اور ہر ایک کو تقریباً 1 سینٹی میٹر موٹی گول ٹکیہ میں چپٹا کریں۔ اسے لکڑی کے فتیت سانچے سے، یا ٹوکری یا چھلنی سے دبائیں تاکہ نقش بن جائے۔","15–20 منٹ بیک کریں یہاں تک کہ کنارے اور نیچے سنہری ہو جائیں، پھر جالی پر ٹھنڈا کریں۔","شیرے کے لیے: پانی کو شہد، دار چینی، الائچی اور کالے لیموں کے ساتھ 2 منٹ پکائیں یہاں تک کہ ذرا گاڑھا ہو جائے، پھر چھان لیں۔","ہر ٹکیہ کو 1 چائے کے چمچ شیرے کے ساتھ پیش کریں، اوپر ڈال کر یا ڈبونے کے لیے الگ۔"],
[WC+"تقریباً 200 گرام کی جگہ 60 گرام چینی، تقریباً 180 ملی لیٹر کی جگہ 60 ملی لیٹر تیل، بغیر چکنائی کا پاؤڈر دودھ، اور ہر ٹکیہ کے لیے تھوڑی مقدار میں ہلکا شہد کا شیرہ۔",
KT+"سالم گندم کے آٹے، پاؤڈر دودھ اور بیکنگ پاؤڈر میں فاسفورس ہوتا ہے؛ ایک ٹکیہ تک رہیں، اور آپ کم سوڈیم والا بیکنگ پاؤڈر اور آدھا سفید آٹا استعمال کر سکتے ہیں۔",
DT+"ایک ٹکیہ میں تقریباً 20 گرام کاربوہائیڈریٹ ہوتے ہیں جن میں 6 گرام اضافی چینی ہے؛ بغیر میٹھے عربی قہوے کے ساتھ ایک ٹکیہ کھائیں اور ممکن ہو تو شیرہ چھوڑ دیں۔",
SF+"ذیابیطس، دل کی صحت اور بلڈ پریشر، گردے کی بیماری (ڈائیلیسس کے بغیر)، ڈائیلیسس کے مریض، سبزی خور۔",
RF+"Encyclopedia Cooking، عربی وکیپیڈیا (Fatit)، Khaleej Kitchen (Qassim kleicha)"],[]))
recs.append(R(8879817,"نجدی سرخ ہریس",
"نجدی ہریس سالم گندم ہے جو گوشت، ٹماٹر اور مصالحوں کے ساتھ کئی گھنٹے آہستہ آہستہ پکائی جاتی ہے، پھر ملائم ہونے تک گھوٹی جاتی ہے اور اوپر پیاز کی کشنہ ڈالی جاتی ہے؛ یہ نجد اور حائل میں خاص مواقع پر مقبول ہے۔ اس ترکیب میں کم چکنائی والا گوشت، ایک چمچ تیل اور کشنہ میں بہت سارے گھی کی جگہ تھوڑا گھی، بغیر نمک والا ٹماٹر پیسٹ اور تھوڑا نمک ہے۔",
"4","1 پیالہ (تقریباً 400 گرام)",
[("ہریس کے لیے","240 گرام ہریس گندم (چھلکا اترا سالم گندم)، دھوئی ہوئی اور 2 گھنٹے بھگوئی ہوئی"),("ہریس کے لیے","600 گرام کم چکنائی والا بغیر ہڈی کا بچھڑے یا جوان اونٹ کا گوشت، نظر آنے والی چربی ہٹائی ہوئی، چکور ٹکڑوں میں"),("ہریس کے لیے","1 کھانے کا چمچ زیتون کا تیل (13.5 گرام)"),("ہریس کے لیے","1 بڑا پیاز، باریک کٹا ہوا (150 گرام)"),("ہریس کے لیے","2 بڑے ٹماٹر، کدوکش کیے ہوئے (250 گرام)"),("ہریس کے لیے","2 کھانے کے چمچ بغیر نمک والا ٹماٹر پیسٹ (30 گرام)"),("ہریس کے لیے","1 چائے کا چمچ ملے جلے سعودی مصالحے (بزار)، 1 چائے کا چمچ ہلدی، ½ چائے کا چمچ پسی سرخ مرچ، ½ چائے کا چمچ الائچی"),("ہریس کے لیے","تقریباً 2.5 لیٹر ابلتا پانی"),("ہریس کے لیے","¾ چائے کا چمچ نمک (4.5 گرام)"),("کشنہ کی تہہ کے لیے","2 چائے کے چمچ گھی (9 گرام)"),("کشنہ کی تہہ کے لیے","1 درمیانا پیاز، پتلے قتلوں میں (100 گرام)"),("کشنہ کی تہہ کے لیے","1 ہری مرچ، کٹی ہوئی (15 گرام)"),("کشنہ کی تہہ کے لیے","½ چائے کا چمچ پسا سوکھا لیموں (لومی)")],
["بڑے بھاری برتن میں تیل گرم کریں اور پیاز نرم ہونے تک پکائیں، پھر گوشت اور مصالحے ڈال کر 8–10 منٹ بھورا کریں۔","کدوکش ٹماٹر اور ٹماٹر پیسٹ ڈال کر 5 منٹ ہلائیں یہاں تک کہ گاڑھا ہو جائے۔","چھنی ہوئی گندم اور ابلتا پانی ڈالیں، ابال آنے دیں، پھر آنچ بہت دھیمی کر کے ڈھانپیں اور 3½–4 گھنٹے پکائیں، وقفے وقفے سے ہلائیں اور ضرورت پر ابلتا پانی ڈالیں (یا پریشر کوکر میں 1½ گھنٹے)۔","آخری گھنٹے میں نمک ڈالیں، پھر ہریس کو گرم ہی گرم لکڑی کے گھوٹنے یا ہینڈ بلینڈر سے گھوٹیں یہاں تک کہ گوشت ریشہ ریشہ ہو کر گندم میں مل جائے۔","کشنہ کے لیے: چھوٹے پین میں گھی گرم کریں اور پیاز سنہری ہونے تک تلیں، پھر 1 منٹ کے لیے مرچ اور سوکھا لیموں ڈالیں۔","ہریس سرونگ ڈش میں پھیلائیں، اوپر کشنہ ڈالیں اور ہرے سلاد کے ساتھ گرم پیش کریں۔"],
[WC+"کم چکنائی والا گوشت، پوری ہانڈی کے لیے 1 کھانے کا چمچ تیل اور 2 چائے کے چمچ گھی بہت سارے مکھن اور گھی کی جگہ، ٹماٹر کی پوری ڈبیا کی جگہ بغیر نمک والا ٹماٹر پیسٹ، اور کم نمک۔",
KT+"سالم گندم اور گوشت میں فاسفورس زیادہ ہوتا ہے، اور ٹماٹر اور ٹماٹر پیسٹ میں پوٹاشیم؛ آدھا ٹماٹر پیسٹ استعمال کریں، ایک حصے تک رہیں (تقریباً 100 گرام پکا ہوا گوشت) اور سالم اناج کے بارے میں اپنے غذائی ماہر سے پوچھیں۔",
DT+"ایک پیالے میں ریشے سے بھرپور سالم اناج سے تقریباً 53 گرام کاربوہائیڈریٹ ہوتے ہیں؛ اسے سلاد کے ساتھ کھائیں اور اوپر چینی نہ ڈالیں۔",
SF+"ذیابیطس، دل کی صحت اور بلڈ پریشر۔",
RF+"Encyclopedia Cooking (encyclopediacooking.com)، Sayidaty Kitchen (hareis with meat and onion)، Saudipedia (popular foods of Hail)"],[]))
